// Panel opened on entering a space. On phones the layer list would cover the chart, so Design starts with the canvas.
// One editor, no space switcher: the rail tool picks the mode. Entering data uses the capture mode (value-locked drag,
// moment chips); styling and notes use the design mode; other tools keep the current mode.
const spaceFor = id => id === 'entry' ? 'capture' : ['design', 'layers', 'notes'].includes(id) ? 'design' : null;
const autoPanel = space => space === 'capture' ? 'entry' : innerWidth < 761 ? '' : 'layers';
const NEXT_EXTRA = [{id:'table',label:'Bảng dữ liệu',icon:'table-2'},{id:'layers',label:'Lớp & nét',icon:'layers-3'},{id:'versions',label:'Phiên bản',icon:'history'},{id:'library',label:'Thư viện ca',icon:'folder-open'},{id:'case',label:'Thông tin ca',icon:'contact-round'}];
function nextClock(c,time){
  const clock=clockAt(c,time).slice(0,5),[h,m]=c.patient.startTime.split(':').map(Number),days=Math.floor((h*60+m+Math.round(time*60))/1440);
  if(!c.patient.date)return clock+(days?' · ngày +'+days:'');
  const d=new Date(c.patient.date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);
  return clock+' · '+new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(d);
}

function nextLayerForField(key){return ['pulse','systolic','diastolic','temperature','protein','acetone','urineVolume'].includes(key)?'mother':['oxyDose','oxyRate','medication','ivFluids'].includes(key)?'medication':['cervix','descent','station','effacement','fluid','moulding','presentation','fetalPosition','occiputPosition','caput','position'].includes(key)?'progress':['contractions','duration','contractionCells'].includes(key)?'contractions':key==='fhr'?'fhr':null}
function nextAssertUnlocked(before,after,design){
  const locked=design.lockedLayers||[],series=design.lockedSeries||[];
  for(const t of new Set([...before.observations,...after.observations].map(o=>o.time))){const a=before.observations.find(o=>o.time===t)||{},b=after.observations.find(o=>o.time===t)||{};for(const f of FIELD_DEFS)if(JSON.stringify(blank(a[f.key])?null:a[f.key])!==JSON.stringify(blank(b[f.key])?null:b[f.key])&&(locked.includes(nextLayerForField(f.key))||series.includes(SERIES_OF[f.key]||f.key)))throw Error('Lớp '+f.label+' đang khóa. Mở khóa trước khi sửa.');}
  if(locked.includes('notes')&&JSON.stringify(before.events)!==JSON.stringify(after.events))throw Error('Lớp chú thích đang khóa.');
  if(locked.includes('header')&&(before.title!==after.title||JSON.stringify(before.patient)!==JSON.stringify(after.patient)))throw Error('Thông tin ca đang khóa.');
}
