  w.parsePaste=()=>{w.importAnchor=w.selection.find(s=>s.type==='point')?.time??null;w.importError='';w.importPreview=null;const lines=w.paste.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<2||lines.length>301){w.importError='Dán hàng tiêu đề và từ 1 đến 300 hàng dữ liệu.';return}const header=lines[0].split('\t'),norm=s=>commandSearch(s).replace(/[^a-z0-9]/g,''),aliases={gio:'time',time:'time',moc:'time',ngay:'date',date:'date',ctc:'cervix',domoctc:'cervix',timthai:'fhr',conco:'contractions',thoigianconco:'duration',mach:'pulse',dautrenve:'descent'};w.columns=header.map(label=>{const name=norm(label.replace(/\([^)]*\)/g,'')),match=FIELD_DEFS.find(f=>norm(f.key)===name||norm(w.label(f.key))===name);return {label,key:aliases[name]||match?.key||'',include:true}});w.importRows=lines.slice(1).map(line=>line.split('\t'));w.importStep=1};
