  w.versionDiff=computed(()=>{const a=versionState(w.versionA),b=versionState(w.versionB);if(!a||!b)return [];const rows=aiDiff(a.case,b.case).map(r=>{const display=r.path.startsWith('events.')&&r.before&&r.after&&r.before.time===r.after.time&&r.before.label===r.after.label;return {...r,scope:display?'design':'data',label:display?'Vị trí / kiểu chú thích · '+r.after.label:r.label,time:r.time}});for(const key of Object.keys(DESIGN_DEFAULTS))if(JSON.stringify(a.design?.[key])!==JSON.stringify(b.design?.[key]))rows.push({scope:'design',label:({font:'Cỡ chữ',rowHeight:'Chiều cao hàng',sectionHeights:'Chiều cao vùng',series:'Màu, nét & ký hiệu',grid:'Độ đậm lưới'}[key]||key),before:JSON.stringify(a.design?.[key]),after:JSON.stringify(b.design?.[key])});return rows.filter(r=>w.versionScope==='all'||r.scope===w.versionScope)});
