  w.focusField=async event=>{if(innerWidth>760||!event.target.matches('input,select,textarea'))return;if(w.sheet==='compact')w.sheet='half';await nextTick();const field=event.target,box=field.closest('.toolbox'),footer=box?.querySelector('.next-record-footer'),header=box?.querySelector('.next-entry-head');if(!box||!footer)return;const r=field.getBoundingClientRect(),top=Math.max(box.getBoundingClientRect().top+64,header?.getBoundingClientRect().bottom||0)+8,bottom=footer.getBoundingClientRect().top-8;if(r.bottom>bottom)box.scrollTop+=r.bottom-bottom;else if(r.top<top)box.scrollTop-=top-r.top};
