  app.component('next-handles',{props:['work'],data:()=>({drag:null}),methods:{down(h,e){e.currentTarget.setPointerCapture(e.pointerId);this.drag={id:h.id,x:e.clientX,y:e.clientY,dx:0,dy:0}},move(e){if(this.drag){this.drag.dx=e.clientX-this.drag.x;this.drag.dy=e.clientY-this.drag.y}},up(h,e){const d=this.drag;this.drag=null;if(d&&Math.hypot(d.dx,d.dy)>2)this.work.dropHandle(h,d.dx,d.dy)},cancel(){this.drag=null},shift(h){return this.drag?.id===h.id?'translate('+(h.kind==='label'?this.drag.dx:0)+'px,'+(h.kind==='section'?this.drag.dy:0)+'px)':''}},template:`<div v-if="work.space==='design'" class="next-handles"><div v-for="r in work.regionFrames()" :key="'frame-'+r.id" class="next-region-frame" :class="{selected:r.selected}" :style="{top:r.top+'px',left:r.left+'px',width:r.width+'px',height:r.height+'px'}" aria-hidden="true"><span>{{r.label}}</span></div><button v-for="h in work.handles()" :key="h.id" type="button" class="next-handle" :class="[h.kind,{dragging:drag&&drag.id===h.id}]" :style="h.kind==='label'?{left:h.x+'px',top:h.y+'px',height:h.length+'px',transform:shift(h)}:{left:h.x+'px',top:h.y+'px',width:h.length+'px',transform:shift(h)}" :title="h.title" :aria-label="h.title" @pointerdown.stop="down(h,$event)" @pointermove="move" @pointerup="up(h,$event)" @pointercancel="cancel" @keydown.esc.stop="cancel" @keydown.left.prevent="work.stepHandle(h,-1)" @keydown.right.prevent="work.stepHandle(h,1)" @keydown.up.prevent="work.stepHandle(h,-1)" @keydown.down.prevent="work.stepHandle(h,1)"><span v-if="drag&&drag.id===h.id&&Math.hypot(drag.dx,drag.dy)>2" class="next-handle-tip">{{work.previewHandle(h,drag.dx,drag.dy)}}</span></button></div>`});
